css:
@page {
  size: A4;
  margin: 5mm 6mm 12mm 6mm;
}

:root {
  --brand: #0f766e;
  --blue: #2f5f9f;
  --soft: #e7f4f2;
  --soft-2: #f3faf9;
  --ink: #12212b;
  --muted: #58707d;
  --line: #d5dde2;
  --card: #ffffff;
}

@font-face {
  font-family: 'CascadiaCode-Bold';
  src: url('/assets/tms/fonts/CascadiaCode-Bold.ttf') format('truetype');
  font-weight: 700;
  font-style: normal;
}

@font-face {
  font-family: 'Noto Naskh Arabic';
  src: url('/assets/tms/fonts/NotoNaskhArabic-VariableFont_wght.ttf') format('truetype');
  font-weight: 400 700;
  font-style: normal;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 0 !important;
}

* {
  box-sizing: border-box;
}

body {
  font-family: Ubuntu, "Segoe UI", Arial, sans-serif;
  font-size: 8.2px;
  color: var(--ink);
}

.quotation-shell {
  position: relative;
}

.sheet {
  position: relative;
  min-height: 278mm;
  padding-bottom: 10mm;
  background: #ffffff;
}

.company-header-box {
  width: 100%;
  border-bottom: 1px solid var(--line);
  padding-bottom: 4px;
  margin-bottom: 4px;
}

.company-header-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.company-header-table td {
  vertical-align: top !important;
  border: 0 !important;
}

.company-info-en {
  width: 36%;
  text-align: left;
  direction: ltr;
  font-size: 9.6px;
  line-height: 1.32;
}

.company-info-ar {
  width: 36%;
  text-align: right;
  direction: rtl;
  font-family: 'Noto Naskh Arabic', serif;
  font-size: 9.7px;
  line-height: 1.32;
}

.company-logo-mid {
  width: 24%;
  text-align: center;
  vertical-align: middle !important;
}

.company-name-en {
  font-size: 12.2px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-name-ar {
  font-size: 12.8px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-line {
  margin-bottom: 1.5px;
}

.company-label {
  font-weight: 600;
  color: var(--brand);
}

.brand-logo-frame {
  display: inline-block;
  min-width: 156px;
  min-height: 82px;
  padding: 1px 3px;
  background: #fff;
  text-align: center;
  vertical-align: middle;
}

.brand-logo {
  display: block;
  max-width: 146px !important;
  max-height: 96px !important;
  width: auto !important;
  height: auto !important;
  margin: 0 auto;
  object-fit: contain;
  vertical-align: middle;
}

.invoice-title-center {
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  margin-top: 4px;
  color: var(--brand);
}

.ar-title {
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
}

.summary-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 3px;
}

.summary-card {
  width: 100%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}

.mini-table {
  width: 100%;
  border-collapse: collapse;
}

.mini-table td {
  padding: 1.6px 0 !important;
  border-bottom: 1px dashed var(--line);
  vertical-align: top !important;
  line-height: 1.12;
}

.mini-table tr:last-child td {
  border-bottom: 0;
}

.mini-label {
  width: 33%;
  color: var(--muted);
  font-weight: 400;
}

.mini-value {
  width: 34%;
  font-weight: 500;
}

.mini-ar {
  font-family: 'Noto Naskh Arabic', serif;
  width: 33%;
  text-align: right;
  direction: rtl;
  color: var(--muted);
}

.party-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 3px;
}

.party-grid > tbody > tr > td {
  border: 0 !important;
  padding: 0 !important;
  vertical-align: top !important;
}

.party-column {
  width: 49%;
}

.party-gap {
  width: 2%;
}

.party-card {
  width: 100%;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
  page-break-inside: avoid;
  break-inside: avoid;
}

.party-title {
  display: table;
  width: 100%;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 3px;
}

.party-title strong {
  display: table-cell;
  color: var(--brand);
  font-size: 9px;
  font-weight: 600;
}

.party-title span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  color: var(--brand);
  direction: rtl;
  text-align: right;
  font-size: 9px;
}

.party-rows {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.party-rows td {
  padding: 1.4px 0 !important;
  border-bottom: 1px dashed var(--line) !important;
  vertical-align: top !important;
  line-height: 1.12;
}

.party-rows tr:last-child td {
  border-bottom: 0 !important;
}

.party-rows td:first-child {
  width: 28%;
  color: var(--muted);
  font-weight: 400;
}

.party-rows td:nth-child(2) {
  width: 46%;
  font-weight: 500;
  padding-right: 8px !important;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.party-rows td:last-child {
  font-family: 'Noto Naskh Arabic', serif;
  width: 26%;
  direction: rtl;
  text-align: right;
  color: var(--muted);
}

.letter-block {
  margin-top: 5px;
  border-top: 1px solid var(--line);
  padding-top: 4px;
}

.top-info {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
}

.top-info td {
  border: 0 !important;
  padding: 2px 0 !important;
  vertical-align: top !important;
  line-height: 1.25;
}

.label-cell {
  width: 72px;
  white-space: nowrap;
}

.value-cell {
  width: auto;
  padding-left: 8px !important;
  overflow-wrap: break-word;
}

.subject-value {
  text-decoration: underline;
}

.dear {
  margin: 5px 0 0 0;
}

.intro {
  margin: 5px 0 0 0;
  line-height: 1.32;
  text-align: left;
}

.intro-small {
  margin: 5px 0 2px 0;
}

.block {
  margin-top: 4px;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}

.block-head {
  display: table;
  width: 100%;
  margin-bottom: 3px;
}

.block-head strong {
  display: table-cell;
  color: var(--brand);
  font-size: 7.6px;
  font-weight: 600;
}

.block-head span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
  text-align: right;
  color: var(--muted);
  font-size: 8px;
}

.items-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  page-break-inside: auto;
  break-inside: auto;
}

.items-table th,
.items-table td {
  border: 1px solid var(--line) !important;
  padding: 2px 3px !important;
  vertical-align: top !important;
  line-height: 1.12;
}

.items-table thead {
  display: table-header-group;
}

.items-table tr {
  page-break-inside: avoid;
  break-inside: avoid;
}

.items-table thead th {
  background: var(--soft) !important;
  color: var(--brand) !important;
  font-size: 7.2px;
  font-weight: 600;
  text-align: center;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.quotation-items-table td {
  font-size: 7.7px;
}

.quotation-items-table .item-name {
  font-weight: 600;
  margin-bottom: 2px;
}

.quotation-items-table .item-code {
  color: var(--muted);
  font-size: 7px;
  line-height: 1.2;
  white-space: pre-line;
}

.num {
  text-align: right;
  direction: ltr;
  white-space: nowrap;
}

.totals-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 3px;
  page-break-inside: avoid;
  break-inside: avoid;
}

.tax-card,
.totals-card {
  width: 49%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}

.summary-spacer {
  width: 2%;
}

.section-kicker {
  color: var(--brand);
  font-weight: 600;
  font-size: 7.4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.totals-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.totals-table td {
  border: 1px solid var(--line) !important;
  padding: 2px 3px !important;
  line-height: 1.12;
}

.totals-table td:first-child {
  color: var(--muted);
  font-weight: 400;
}

.totals-table td:last-child {
  text-align: right;
  direction: ltr;
}

.totals-table tr:last-child td {
  background: var(--brand) !important;
  color: #ffffff !important;
  font-weight: 600;
  -webkit-text-fill-color: #ffffff !important;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.terms-block {
  margin-top: 5px;
  page-break-inside: avoid;
  break-inside: avoid;
}

.terms-list {
  margin: 0 0 0 16px;
  padding-left: 12px;
  line-height: 1.2;
  font-size: 8.4px;
}

.terms-list li {
  margin: 2px 0;
}

.po-line {
  margin: 8px 0 0 0;
  font-size: 8.6px;
  page-break-inside: avoid;
}

.sign-block {
  margin: 18px 0 0 0;
  font-size: 8.5px;
  page-break-inside: avoid;
}

.sign-block p {
  margin: 0 0 5px 0;
}

.stamp-sign-row {
  display: table;
  width: 240px;
  margin: 6px 0 8px 0;
  table-layout: fixed;
}

.signature-box,
.stamp-box {
  display: table-cell;
  width: 50%;
  vertical-align: middle;
  text-align: left;
}

.signature-box img {
  max-width: 100px;
  max-height: 45px;
  object-fit: contain;
}

.stamp-box img {
  max-width: 90px;
  max-height: 90px;
  object-fit: contain;
}

.email {
  color: #0645ad;
  text-decoration: underline;
}

.page-break {
  page-break-after: always;
  break-after: page;
  height: 0;
  display: block;
}

.footer-page-break {
  page-break-before: auto;
  break-before: auto;
  height: 8mm;
  display: block;
}

.footer-bar {
  position: relative !important;
  left: auto !important;
  right: auto !important;
  bottom: auto !important;

  display: table;
  table-layout: fixed;
  width: 100%;
  min-height: 13mm;

  background-color: var(--blue) !important;
  color: #ffffff !important;

  font-size: 8.8px;
  font-weight: bold;
  padding: 0 8px;
  margin-top: 8mm;

  page-break-inside: avoid;
  break-inside: avoid;

  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

.footer-bar span {
  display: table-cell;
  text-align: center;
  vertical-align: middle;

  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;

  padding: 0 3px;
  overflow-wrap: break-word;
  word-break: normal;
}

.footer-bar,
.footer-bar * {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
}

@media print {
  .footer-bar {
    position: relative !important;
    background-color: var(--blue) !important;
    color: #ffffff !important;
  }

  .footer-bar,
  .footer-bar * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
}

[dir="rtl"],
.company-info-ar,
.company-name-ar,
.mini-ar,
.party-title span,
.party-rows td:last-child,
.block-head span,
.ar-title {
  font-family: 'Noto Naskh Arabic', serif !important;
}
